create table public.be_fundraiser_analysis (
 project_id uuid primary key references public.be_fundraising_projects(id) on delete cascade,
 analysis jsonb not null check(jsonb_typeof(analysis)='object'),
 selected boolean not null default false, selected_by uuid references auth.users(id) on delete set null, selected_at timestamptz
);
alter table public.be_fundraiser_analysis enable row level security;
revoke all on public.be_fundraiser_analysis from anon;
grant select,insert,update,delete on public.be_fundraiser_analysis to authenticated;
create policy fundraiser_analysis_admin_only on public.be_fundraiser_analysis for all to authenticated
 using(exists(select 1 from public.be_staff_memberships where user_id=(select auth.uid()) and staff_role='admin'))
 with check(exists(select 1 from public.be_staff_memberships where user_id=(select auth.uid()) and staff_role='admin'));
create or replace function public.be_choose_fundraiser_idea(p_project_id uuid)
returns void language plpgsql security invoker set search_path='' as $$
begin
 if auth.uid() is null or not exists(select 1 from public.be_staff_memberships where user_id=auth.uid() and staff_role='admin') then raise exception 'School administrator access required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(601116);
 if not exists(select 1 from public.be_fundraiser_analysis a join public.be_fundraising_projects p on p.id=a.project_id where p.id=p_project_id and not p.published and p.status='planning') then raise exception 'This draft fundraising idea is unavailable'; end if;
 update public.be_fundraiser_analysis set selected=false,selected_by=null,selected_at=null where selected;
 update public.be_fundraiser_analysis set selected=true,selected_by=auth.uid(),selected_at=now() where project_id=p_project_id;
 update public.be_fundraiser_research set selected=false,selected_by=null,selected_at=null where selected;
 update public.be_fundraiser_research set selected=true,selected_by=auth.uid(),selected_at=now() where project_id=p_project_id;
end $$;
revoke all on function public.be_choose_fundraiser_idea(uuid) from public,anon;
grant execute on function public.be_choose_fundraiser_idea(uuid) to authenticated;
-- Keep older clients consistent with the single saved preference.
create or replace function public.be_choose_fundraiser_outing(p_project_id uuid)
returns void language plpgsql security invoker set search_path='' as $$
begin perform public.be_choose_fundraiser_idea(p_project_id); end $$;
update public.be_fundraising_projects set title='VWS Firefighting Open Day — family learning event' where title='Family outing proposal: VWS Firefighting Open Day' and not published;
update public.be_fundraising_projects set title='Streetopia — family art event' where title='Family outing proposal: Streetopia Art & Creativity' and not published;
update public.be_fundraising_projects set title='Museum of Childhood — family learning event' where title='Family visit proposal: Museum of Childhood' and not published;
update public.be_fundraising_projects set title='Iziko Planetarium — space learning event' where title='Family visit proposal: Iziko Planetarium' and not published;
update public.be_fundraising_projects set description=replace(description,'outing','learning event'),goal_description=replace(goal_description,'outing','learning event') where not published;
update public.be_fundraiser_research set host_schedule=replace(host_schedule,'outing','event'), public_description=replace(public_description,'outing','event');
update public.be_school_events set description=replace(description,'outing','event') where not published;
insert into public.be_fundraising_projects(title,description,goal_description,status,published) select 'Butterflies Pre-order Bake Sale','Sell prepaid packs; purchase ingredients only after the order deadline. School keeps sales less ingredients, packaging and setup. Planning proposal only; no date, price or booking confirmed.','Support school learning resources','planning',false where not exists(select 1 from public.be_fundraising_projects where title='Butterflies Pre-order Bake Sale');
insert into public.be_fundraiser_analysis(project_id,analysis) select id,'{"title": "Butterflies Pre-order Bake Sale", "kind": "School-led idea", "model": "Sell prepaid packs; purchase ingredients only after the order deadline. School keeps sales less ingredients, packaging and setup.", "unit": "packs", "price": 35, "variable": 18, "fixed": 150, "counts": [15, 30, 50], "preparation": "3 weeks; proposed collection 14:00\u201316:00, date to be chosen.", "venue": "School collection point, subject to approval", "learning": "Counting, following a recipe and community participation.", "verified": "No supplier prices, orders or donated ingredients confirmed. R18 per pack is an ingredient/packaging allowance, not a retail quote.", "checks": "Cost a sample recipe; agree pack size, allergens, safe preparation, kitchen capacity and collection. Get enough preorders before spending. Unsold extras are not assumed.", "verdict": "Good first pilot: preorders control waste and cash exposure.", "sources": [], "cost_basis": "School planning allowances only; no supplier quotation or demand survey yet. Fixed costs include a small consumables/contingency allowance. Volunteer time and existing school venue are assumed donated. Any paid labour, venue hire, transport, payment fees or extra costs must be added before setting a price.", "checked_on": "2026-11-16"}'::jsonb from public.be_fundraising_projects where title='Butterflies Pre-order Bake Sale' and not published on conflict(project_id) do update set analysis=excluded.analysis;
