insert into public.be_fundraiser_analysis(project_id,analysis) select id,'{"title": "Iziko Mobile Museum \u2014 learning at school", "kind": "New visiting-provider idea", "model": "Illustrative R25 voluntary contribution per participating family, with a reserved R260 provider visit allowance plus R100 setup. Keep a free participation route.", "unit": "contributing families", "price": 25, "variable": 0, "fixed": 360, "counts": [10, 20, 30], "preparation": "Ask about availability 6\u20138 weeks ahead; proposed weekday 10:00\u201311:00, duration and date unconfirmed.", "venue": "Butterflies Educare, subject to provider acceptance", "learning": "Museum objects and age-adapted learning without group transport.", "verified": "Official tariff page lists R260 per mobile visit, while the education booking page says free. This conflict is unresolved; R260 is a provisional allowance, not a quote.", "checks": "Ask outreach contact sharmans@iziko.org.za / 021 481 3812 to confirm eligibility, charge, travel, capacity, topic and preschool duration. No school collection associated with the provider without agreement.", "verdict": "Potentially practical; verify fee conflict. If free, model surplus rises by R260.", "sources": ["https://www.iziko.org.za/visit/", "https://www.iziko.org.za/education/admin/"], "cost_basis": "Fixed R360 = disputed R260 visit tariff allowance + estimated R100 setup. No extra travel fee or paid staff assumed. Revised quote must replace this before a decision to spend.", "checked_on": "2026-11-16"}'::jsonb from public.be_fundraising_projects where title='Iziko Mobile Museum — learning at school' and not published on conflict(project_id) do update set analysis=excluded.analysis;
insert into public.be_fundraising_projects(title,description,goal_description,status,published) select 'Cape Town Science Centre — discovery event','Illustrative R110 learner package = R85 group admission + R5 estimated materials + R20 school contribution. This is a higher-cost comparator, not a free-event recommendation. Planning proposal only; no date, price or booking confirmed.','Support school learning resources','planning',false where not exists(select 1 from public.be_fundraising_projects where title='Cape Town Science Centre — discovery event');
insert into public.be_fundraiser_analysis(project_id,analysis) select id,'{"title": "Cape Town Science Centre \u2014 discovery event", "kind": "New existing-venue benchmark", "model": "Illustrative R110 learner package = R85 group admission + R5 estimated materials + R20 school contribution. This is a higher-cost comparator, not a free-event recommendation.", "unit": "learner places", "price": 110, "variable": 90, "fixed": 200, "counts": [16, 25, 35], "preparation": "Plan 6\u20138 weeks ahead; suggested weekday 10:00\u201312:00, slot and date unconfirmed.", "venue": "370B Main Road, Observatory", "learning": "Hands-on discovery; select preschool activities with the centre.", "verified": "2026 booking form: groups larger than 15 R85 per person; one supervising adult per ten learners free; extra adults R45. R300 deposit for up to 30 learners, then R10 per additional learner.", "checks": "Confirm preschool programme, group size, deposit treatment, chaperones, optional workshop costs and cancellation terms. Model assumes deposit is credited to total, not a second fee; verify. Transport/adults extra.", "verdict": "Costs families more for the same R20 per-place contribution; lower priority for a low-cost campaign.", "sources": ["https://www.ctsc.org.za/wp-content/uploads/2026/01/CTSC-School-Group-BOOKING-FORM-2026-updated-Feb-2026.pdf", "https://www.ctsc.org.za/schools/book-a-school-group-visit/"], "cost_basis": "R85 group tariff is published subject to eligibility. R5 materials and R200 setup estimated. No workshop, transport, additional adult or paid staff cost included.", "checked_on": "2026-11-16"}'::jsonb from public.be_fundraising_projects where title='Cape Town Science Centre — discovery event' and not published on conflict(project_id) do update set analysis=excluded.analysis;
update public.be_fundraiser_analysis a set selected=r.selected,selected_by=r.selected_by,selected_at=r.selected_at from public.be_fundraiser_research r where r.project_id=a.project_id;
update public.be_fundraiser_analysis set analysis='{"title": "Butterflies Pre-order Bake Sale", "kind": "School-led idea", "model": "Sell prepaid packs; purchase ingredients only after the order deadline. School keeps sales less ingredients, packaging and setup.", "unit": "packs", "price": 35, "variable": 18, "fixed": 150, "counts": [15, 30, 50], "preparation": "3 weeks; proposed collection 14:00\u201316:00, date to be chosen.", "venue": "School collection point, subject to approval", "learning": "Counting, following a recipe and community participation.", "verified": "No supplier prices, orders or donated ingredients confirmed. R18 per pack is an ingredient/packaging allowance, not a retail quote. BBC Children in Need lists bake sales among fundraising ideas. That is method inspiration only; Butterflies would run its own separate campaign.", "checks": "Cost a sample recipe; agree pack size, allergens, safe preparation, kitchen capacity and collection. Get enough preorders before spending. Unsold extras are not assumed.", "verdict": "Good first pilot: preorders control waste and cash exposure.", "sources": ["https://www.bbcchildreninneed.co.uk/fundraising/more-fundraising-ideas/"], "cost_basis": "School planning allowances only; no supplier quotation or demand survey yet. Fixed costs include a small consumables/contingency allowance. Volunteer time and existing school venue are assumed donated. Any paid labour, venue hire, transport, payment fees or extra costs must be added before setting a price.", "checked_on": "2026-11-16"}'::jsonb where project_id in (select id from public.be_fundraising_projects where title='Butterflies Pre-order Bake Sale');
update public.be_fundraiser_analysis set analysis='{"title": "Sponsored Story Week", "kind": "New school-led idea", "model": "Adults pledge a flat R50 for a child\u2019s week of shared reading; no per-book competition and no requirement to pay to participate.", "unit": "collected pledges", "price": 50, "variable": 0, "fixed": 100, "counts": [10, 25, 40], "preparation": "2\u20133 weeks preparation; one school week, with optional 10-minute daily family reading.", "venue": "School and home", "learning": "Language, family reading and confidence.", "verified": "Original school proposal; no partner, pledges or materials prices confirmed. Existing books and volunteer time assumed. Read for Good documents sponsored reading as a fundraising method. This proposal is an independent Butterflies campaign, not enrolment in that UK charity programme or a claim to its branding/rewards.", "checks": "Use flat pledges, record collections rather than promises, keep participation free and do not publish child rankings or family donation amounts.", "verdict": "Promising low-cost pilot; depends on actual collected pledges.", "sources": ["https://readforgood.org/about-us/"], "cost_basis": "School planning allowances only; no supplier quotation or demand survey yet. Fixed costs include a small consumables/contingency allowance. Volunteer time and existing school venue are assumed donated. Any paid labour, venue hire, transport, payment fees or extra costs must be added before setting a price.", "checked_on": "2026-11-16"}'::jsonb where project_id in (select id from public.be_fundraising_projects where title='Sponsored Story Week');
update public.be_fundraiser_analysis set analysis='{"title": "Grow & Give Seedling Sale", "kind": "New school-led idea", "model": "Sell R20 seedling pots grown by the school; R8 per pot allowed for seed, growing medium and container.", "unit": "pots sold", "price": 20, "variable": 8, "fixed": 120, "counts": [10, 30, 50], "preparation": "4\u20136 weeks growing lead time; proposed Friday collection 14:00\u201316:00.", "venue": "School collection point", "learning": "Plant life cycles, care and counting.", "verified": "R8 per pot and R120 setup are estimates; no nursery or supplier quote. Donated containers are assumed clean and suitable. RHS school-gardening guidance includes plant sales as a fundraising method; it does not establish local prices or demand.", "checks": "Choose non-toxic plants, obtain material prices, test germination, allow losses and take preorders. Budget is per saleable pot, not per seed planted.", "verdict": "Small, educational fundraiser; growing failures and low demand reduce surplus.", "sources": ["https://www.rhs.org.uk/education-learning/school-gardening/resources/getting-started/raising-money-using-your-school-garden"], "cost_basis": "School planning allowances only; no supplier quotation or demand survey yet. Fixed costs include a small consumables/contingency allowance. Volunteer time and existing school venue are assumed donated. Any paid labour, venue hire, transport, payment fees or extra costs must be added before setting a price.", "checked_on": "2026-11-16"}'::jsonb where project_id in (select id from public.be_fundraising_projects where title='Grow & Give Seedling Sale');

create or replace function public.be_approve_fundraiser(p_project_id uuid,p_title text,p_description text,p_goal text,p_starts_at timestamptz,p_ends_at timestamptz,p_venue text,p_approved boolean)
returns uuid language plpgsql security invoker set search_path='' as $$
declare v_project public.be_fundraising_projects%rowtype; v_event uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.be_staff_memberships where user_id=auth.uid() and staff_role='admin') then raise exception 'School administrator access required' using errcode='42501'; end if;
 if exists(select 1 from public.be_fundraiser_research where project_id=p_project_id and not logistics_confirmed) then raise exception 'This researched event still needs organiser, cost and booking confirmation by the development team before publication'; end if;
 if p_approved is distinct from true then raise exception 'Confirm principal approval before publishing'; end if;
 if p_title is null or length(trim(p_title)) not between 3 and 140 or p_description is null or length(trim(p_description)) not between 15 and 1200 or p_venue is null or length(trim(p_venue)) not between 3 and 140 or length(coalesce(p_goal,''))>250 then raise exception 'Check the public title, description, goal and venue'; end if;
 if p_starts_at is null or p_starts_at<=now() or p_ends_at is null or p_ends_at<=p_starts_at then raise exception 'Choose a future start and an end after it'; end if;
 select * into v_project from public.be_fundraising_projects where id=p_project_id for update;
 if not found then raise exception 'Fundraising proposal not found'; end if;
 if v_project.status='completed' then raise exception 'A completed fundraiser cannot be reopened here'; end if;
 v_event:=v_project.calendar_event_id;
 if exists(select 1 from public.be_school_events where published and id is distinct from v_event and lower(trim(venue))=lower(trim(p_venue)) and starts_at<p_ends_at and coalesce(ends_at,starts_at+interval '1 hour')>p_starts_at) then raise exception 'This venue already has a published event at that time'; end if;
 if v_event is null then
 insert into public.be_school_events(title,description,starts_at,ends_at,venue,published) values(trim(p_title),trim(p_description),p_starts_at,p_ends_at,trim(p_venue),true) returning id into v_event;
 else
 update public.be_school_events set title=trim(p_title),description=trim(p_description),starts_at=p_starts_at,ends_at=p_ends_at,venue=trim(p_venue),published=true where id=v_event;
 if not found then raise exception 'Linked calendar event not found'; end if;
 end if;
 update public.be_fundraising_projects set title=trim(p_title),description=trim(p_description),goal_description=nullif(trim(coalesce(p_goal,'')),''),calendar_event_id=v_event,published=true,status='active' where id=p_project_id;
 return v_event;
end $$;
revoke all on function public.be_approve_fundraiser(uuid,text,text,text,timestamptz,timestamptz,text,boolean) from public,anon;
grant execute on function public.be_approve_fundraiser(uuid,text,text,text,timestamptz,timestamptz,text,boolean) to authenticated;

update public.be_school_events e set title=p.title from public.be_fundraising_projects p where p.calendar_event_id=e.id and not e.published and not p.published;
